@-moz-document domain("laravel-news.com") {
/* your full CSS here */

	input,
	.card,
	.site-main,
	.bg-white {
		background: #102027;
	}

	.post__content.truncate:after {
		background-image: none;
	}

	.pb-24.sm\:pb-32.lg\:max-w-4xl.items-end.relative.mx-auto.grid.w-full.max-w-2xl.gap-x-16.gap-y-12.px-6.pt-10 {
		display: none;
	}

	.mt-6.grid.gap-x-20.gap-y-12.lg\:grid-cols-5 .lg\:col-span-2 {
		display: none;
	}

	section.relative.mx-auto.w-full.max-w-2xl.px-6.py-16.sm\:py-20.lg\:max-w-4xl {
		max-width: 80rem;
	}

	.mt-6.grid.gap-x-20.gap-y-12.lg\:grid-cols-5 .lg\:col-span-3 {
		grid-column: span 5 / span 5;
	}

	.mt-6.grid.gap-x-20.gap-y-12.lg\:grid-cols-5 .lg\:col-span-3 ul.divide-y.divide-gray-100 {
		display: grid;
		grid-gap: 1rem;
		/** grid-template-columns: repeat(5, 1fr); */
		width: 100%;
	}

	.mt-6.grid.gap-x-20.gap-y-12.lg\:grid-cols-5 .lg\:col-span-3 ul.divide-y.divide-gray-100 > li {
		padding: 1rem;
		border: 1px solid gray;
		background: rgb(2, 2, 2);

		display: flex;
		flex-direction: column;
		align-items: flex-start;
		justify-content: flex-start;

		min-width: 0;
		overflow: hidden;
	}

	li.flex.flex-wrap.items-center.justify-between.gap-x-6.gap-y-4.py-5.sm\:flex-nowrap .group.relative {
		display: flex;
		flex-direction: column;
		flex-grow: 1;
		height: 100%;
	}

	li.flex.flex-wrap.items-center.justify-between.gap-x-6.gap-y-4.py-5.sm\:flex-nowrap .group.relative .-mx-0\.5 {
		flex-grow: 1;
	}

	.mt-1.flex.items-center.gap-x-2.text-xs.leading-5.text-gray-600.transition.group-hover\:text-gray-600\/60 {
		flex-direction: column;
	}
}

